'use strict';
// Builds caravan-engine.js (classic script on globalThis.Silk) from the verified ESM engine in caravan-demo/engine/ — the same
// files the standalone playtest runs. No logic is rewritten: imports are dropped (all modules share one scope, no name
// collisions), `export` keywords are stripped, and every exported name is published on S.caravanEngine.
// Usage: node tests/tools/bundle-caravan-engine.js   (rerun after any change under caravan-demo/engine/; caravan.test.js proves parity)
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const root = path.join(__dirname, '..', '..'), src = path.join(root, 'caravan-demo', 'engine');
const ORDER = ['data.js', 'pyrandom.js', 'core.js', 'generator.js', 'stress.js', 'session.js', 'game.js'];
const exported = [], parts = [], hashes = {};
for (const f of ORDER) {
  let code = fs.readFileSync(path.join(src, f), 'utf8'); hashes[f] = crypto.createHash('sha256').update(code).digest('hex').slice(0, 16);
  code = code.replace(/^import\s*\{[^}]*\}\s*from\s*'[^']+';\s*$/gm, '');
  if (/^import\b/m.test(code)) throw new Error('unsupported import form in ' + f);
  code = code.replace(/^export\s+(function\*?|class|const|let)\s+([A-Za-z_$][\w$]*)(.*)$/gm, (m, kw, name, rest) => { exported.push(name); if (kw === 'const' || kw === 'let') for (const x of rest.matchAll(/,\s*([A-Za-z_$][\w$]*)\s*=/g)) exported.push(x[1]); return kw + ' ' + name + rest; });
  if (/^export\b/m.test(code)) throw new Error('unsupported export form in ' + f);
  parts.push('// ---- caravan-demo/engine/' + f + ' (sha256 ' + hashes[f] + ') ----\n' + code.trim());
}
const out = '(function (S) {\n\'use strict\';\n// GENERATED by tests/tools/bundle-caravan-engine.js from caravan-demo/engine/*.js — do not edit; the ESM files are the source.\n' +
  parts.join('\n\n') + '\n\nS.caravanEngine = Object.freeze({ ' + exported.join(', ') + ', sources: ' + JSON.stringify(hashes) + ' });\n})(globalThis.Silk = globalThis.Silk || {});\n';
fs.writeFileSync(path.join(root, 'caravan-engine.js'), out);
console.log('caravan-engine.js', out.length, 'bytes; exports:', exported.length, exported.join(' '));
